import requests
from datetime import datetime

class AccessControl:
    def __init__(self, blocked_url):
        self.blocked_url = blocked_url
        self.access_log = []

    def block_access(self, url):
        if url == self.blocked_url:
            return True
        else:
            return False

    def log_access(self, user_agent, ip_address):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        access_log_entry = {
            "timestamp": timestamp,
            "user_agent": user_agent,
            "ip_address": ip_address
        }
        self.access_log.append(access_log_entry)

    def check_access(self, url):
        if self.blocked_url in url:
            return True
        else:
            return False

def main():
    blocked_url = "http://example.com"
    access_control = AccessControl(blocked_url)

    # Simulate a request to the blocked URL
    try:
        response = requests.get(blocked_url, allow_redirects=False)

        if response.status_code == 403:
            print("Access denied")
        else:
            print(f"Request to {blocked_url} was successful.")

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()
```

This script will block access to the specified URL by returning a 403 Forbidden status code. The `AccessControl` class has methods for blocking access, logging access attempts, and checking if a URL is blocked.

